// AuditScreen — generated by `mcn build --target flutter` for `audit_log`.
// Who changed what, and when.
import 'dart:async';

import 'package:flutter/material.dart';

import 'api.dart';
import 'widgets.dart';

class AuditScreen extends StatefulWidget {
  const AuditScreen({super.key, this.title = 'Activity'});

  final String title;

  @override
  State<AuditScreen> createState() => _AuditScreenState();
}

class _AuditScreenState extends State<AuditScreen> {
  final _rows = <Map<String, dynamic>>[];
  int _total = 0;
  int _page = 1;
  bool _loading = true;
  String _error = '';
  String _search = '';
  Timer? _debounce;

  @override
  void initState() {
    super.initState();
    _load(reset: true);
  }

  @override
  void dispose() {
    _debounce?.cancel();
    super.dispose();
  }

  Future<void> _load({bool reset = false}) async {
    if (reset) _page = 1;
    setState(() {
      _loading = true;
      _error = '';
    });
    try {
      final d = await api.get('/list_audit_log', {
        'page': '$_page',
        'page_size': '30',
        if (_search.isNotEmpty) 'search': _search,
      });
      setState(() {
        if (reset) _rows.clear();
        _rows.addAll([for (final i in (d['items'] as List? ?? const [])) Map<String, dynamic>.from(i as Map)]);
        _total = (d['total'] as num?)?.toInt() ?? _rows.length;
      });
    } catch (e) {
      setState(() => _error = e.toString());
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  String _change(String action, dynamic v) {
    if (action == 'update' && v is List && v.length == 2) return '${mcnStr(v[0])} → ${mcnStr(v[1])}';
    return mcnStr(v);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Column(children: [
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
        child: TextField(
          onChanged: (t) {
            _debounce?.cancel();
            _debounce = Timer(const Duration(milliseconds: 350), () {
              _search = t.trim();
              _load(reset: true);
            });
          },
          decoration: const InputDecoration(
              hintText: 'Search activity…', prefixIcon: Icon(Icons.search),
              isDense: true, border: OutlineInputBorder()),
        ),
      ),
      if (_error.isNotEmpty)
        Padding(padding: const EdgeInsets.symmetric(horizontal: 16), child: McnAlert(_error, destructive: true)),
      Expanded(
        child: RefreshIndicator(
          onRefresh: () => _load(reset: true),
          child: ListView.builder(
            padding: const EdgeInsets.fromLTRB(12, 0, 12, 24),
            itemCount: _rows.length + (_rows.length < _total ? 1 : 0),
            itemBuilder: (context, i) {
              if (i == _rows.length) {
                return TextButton(
                    onPressed: _loading
                        ? null
                        : () {
                            _page += 1;
                            _load();
                          },
                    child: const Text('Load more'));
              }
              final r = _rows[i];
              final action = mcnStr(r['action']);
              final changes = r['changes'] is Map ? (r['changes'] as Map) : const {};
              return Card(
                child: ExpansionTile(
                  title: Text(mcnStr(r['summary'])),
                  subtitle: Text('${mcnStr(r['user_email']).isEmpty ? 'system' : mcnStr(r['user_email'])} · '
                      '${mcnStr(r['at']).replaceFirst('T', ' ')} · ${mcnStr(r['entity'])}'
                      '${r['entity_id'] != null ? ' #${r['entity_id']}' : ''}'),
                  leading: McnBadge(action.replaceAll('_', ' '),
                      color: badgeColor(action == 'create' ? 'done' : action == 'delete' ? 'failed' : action == 'update' ? 'new' : 'pending')),
                  childrenPadding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
                  children: [
                    for (final e in changes.entries)
                      Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        SizedBox(width: 110, child: Text(e.key.toString(), style: theme.textTheme.labelMedium)),
                        Expanded(child: Text(_change(action, e.value))),
                      ]),
                  ],
                ),
              );
            },
          ),
        ),
      ),
    ]);
  }
}
